from pathlib import Path
r=Path('.')
for p in r.glob('*.html'):
 s=p.read_text(encoding='utf-8');s=s.replace('<button type="button" class="company-option">Techno Farm</button>','<a class="company-option" href="farm/index.html">Techno Farm</a>');p.write_text(s,encoding='utf-8')
f=r/'farm';f.mkdir(exist_ok=True)
logo='../images/Farm/Green%20Techno%20Farm%20Logo.png'
def photo(name,alt,cls=''):
 path = {'farm-2.jpg':'../assets/media/farm-IMG_3243-1600.webp'}.get(name, '../images/Farm/'+name)
 return f'<img class="{cls}" src="{path}" alt="{alt}" loading="lazy" decoding="async">'
def btn(text,url,yellow=False):return f'<a class="button {"yellow" if yellow else ""}" href="{url}">{text}<span aria-hidden="true">&#8594;</span></a>'
